import{_ as t,c as o,o as s,a3 as a}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Activity analysis","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/reporting/activity-analysis.md","filePath":"master/sales/crm/reporting/activity-analysis.md","lastUpdated":1793789158000}'),i={name:"master/sales/crm/reporting/activity-analysis.md"};function r(n,e,l,h,g,p){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="activity-analysis" tabindex="-1">Activity analysis <a class="header-anchor" href="#activity-analysis" aria-label="Permalink to &quot;Activity analysis&quot;">​</a></h1><p>Activity analysis lists the activities your team has finished on leads and opportunities. You use it to see who did what and when, which activity types your team uses most, and how the work is spread across salespeople and teams.</p><blockquote><p><strong>In simple words:</strong> It is a log of finished follow-ups, with a count you can group and chart.</p></blockquote><p>Open <code>CRM → Reporting → Activities</code>. The page title is <strong>Activities Analysis</strong>.</p><h2 id="the-report-page" tabindex="-1">The report page <a class="header-anchor" href="#the-report-page" aria-label="Permalink to &quot;The report page&quot;">​</a></h2><p>The page has two views: <strong>List</strong> and <strong>Graph</strong>.</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>My Activities:</em></strong> Activities that you finished or that were assigned to you. This tab opens first.</li><li><strong><em>Leads:</em></strong> Activities done on leads.</li><li><strong><em>Opportunities:</em></strong> Activities done on opportunities.</li><li><strong><em>This Month:</em></strong> Activities finished since the first day of this month.</li></ul><p>The <strong>Default</strong> tab shows all activities.</p><h3 id="default-filter" tabindex="-1">Default filter <a class="header-anchor" href="#default-filter" aria-label="Permalink to &quot;Default filter&quot;">​</a></h3><p>The report starts with the rule <strong>Completion Date is after</strong> one year ago. Edit or remove it to see older activities.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p><strong>Done On</strong>, <strong>Activity Type</strong>, <strong>Summary</strong>, <strong>Lead / Opportunity</strong>, <strong>Type</strong>, <strong>Assigned To</strong>, <strong>Done By</strong>, <strong>Salesperson</strong> and <strong>Sales Team</strong>. Use the column toggle to add <strong>Stage</strong> and <strong>Due Date</strong>. The last column shows the <strong>Count</strong>.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to search by summary or by lead name.</li><li>Use the <strong>Salespeople</strong> and <strong>Sales Teams</strong> filters.</li><li>Use the filter builder for rules on <strong>Activity Type</strong>, <strong>Assigned To</strong>, <strong>Done By</strong>, <strong>Type</strong> and <strong>Completion Date</strong>.</li><li>Click a row to open the lead or opportunity.</li><li>Select rows and export them.</li></ul><h2 id="group-by" tabindex="-1">Group by <a class="header-anchor" href="#group-by" aria-label="Permalink to &quot;Group by&quot;">​</a></h2><p>The options are:</p><ul><li><strong>Activity Type</strong>, <strong>Type</strong></li><li><strong>Assigned To</strong>, <strong>Done By</strong></li><li><strong>Completion Date</strong>, <strong>Activity Creation Date</strong> (grouped by month)</li><li><strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Stage</strong>, <strong>Company</strong></li><li><strong>Expected Closing</strong>, <strong>Closed Date</strong> (taken from the lead or opportunity, grouped by month)</li></ul><p><strong>Type</strong> here means lead or opportunity.</p><h2 id="measure" tabindex="-1">Measure <a class="header-anchor" href="#measure" aria-label="Permalink to &quot;Measure&quot;">​</a></h2><p>This report has one measure: <strong>Count</strong>. It is the number of finished activities in the group.</p><h2 id="the-graph-view" tabindex="-1">The Graph view <a class="header-anchor" href="#the-graph-view" aria-label="Permalink to &quot;The Graph view&quot;">​</a></h2><ol><li>Click <strong>Graph</strong> in the view switch.</li><li>Keep <strong>Count</strong> as the measure.</li><li>Choose <strong>Group by</strong>. The default is <strong>Completion Date</strong>, so each bar is one month.</li><li>Choose <strong>Split by</strong>. The default is <strong>Activity Type</strong>, so each bar shows calls, emails and so on in colours.</li></ol><h2 id="read-the-report" tabindex="-1">Read the report <a class="header-anchor" href="#read-the-report" aria-label="Permalink to &quot;Read the report&quot;">​</a></h2><p><strong>Example:</strong> Your team wants to know who calls customers.</p><ol><li>Open the <strong>Opportunities</strong> tab.</li><li>Group by <strong>Done By</strong>. Each person shows their count.</li><li>In the graph, split by <strong>Activity Type</strong>. You see how many calls, emails and meetings each month held.</li></ol><p>If the list says <strong>No Activities Analysis</strong>, no one has finished an activity in the period yet. Widen the <strong>Completion Date</strong> rule or finish an activity first.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>A row is added when an activity on a lead or opportunity is marked done. Open activities do not appear here.</li><li>Each row keeps the salesperson, team and stage that the record had when the activity was done.</li><li><strong>Assigned To</strong> is who the activity was planned for. <strong>Done By</strong> is who finished it. They can differ.</li><li>To schedule activities, see <a href="./../pipeline/schedule-activities.html">Schedule activities</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../pipeline/schedule-activities.html">Schedule activities</a></li><li><a href="./../../../getting-started/activities.html">Activities</a></li><li><a href="./">Reporting overview</a></li></ul>',31)]))}const u=t(i,[["render",r]]);export{c as __pageData,u as default};
